    "html": "\u003c!doctype html>\n\u003chtml lang=\"ko\">\n\u003chead>\n  \u003cmeta charset=\"UTF-8\">\n  \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  \u003ctitle>표지\u003c/title>\n  \u003cstyle>\n    * { box-sizing: border-box; }\n    html, body { width: 1280px; height: 800px; margin: 0; }\n    body {\n      position: relative;\n      overflow: hidden;\n      background: #fff;\n      color: #16263d;\n      font-family: \"Pretendard\", \"Apple SD Gothic Neo\", \"Malgun Gothic\", sans-serif;\n      -webkit-font-smoothing: antialiased;\n    }\n    .cover-top {\n      position: absolute;\n      top: 55px;\n      left: 72px;\n      right: 72px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding-bottom: 25px;\n      border-bottom: 1px solid #dfe4eb;\n    }\n    .cover-project { font-size: 27px; font-weight: 800; letter-spacing: 1.5px; }\n    .cover-category { color: #7b8592; font-size: 12px; font-weight: 600; letter-spacing: 1.4px; }\n    .cover-title-position { position: absolute; top: 227px; left: 72px; width: 1136px; }\n    .cover-title { width: 1136px; }\n    .cover-title-accent { width: 40px; height: 4px; margin-bottom: 31px; background: #365d87; }\n    .cover-title h1 { margin: 0; font-size: 54px; font-weight: 750; line-height: 1.28; letter-spacing: -2px; }\n    .cover-title p { margin: 14px 0 0; color: #62738a; font-size: 33px; font-weight: 400; line-height: 1.4; letter-spacing: -0.8px; }\n    .cover-metadata-position { position: absolute; bottom: 71px; left: 72px; width: 1136px; }\n    .cover-metadata { display: grid; grid-template-columns: 1.4fr 0.8fr 1fr 1fr; width: 1136px; margin: 0; padding-top: 27px; border-top: 1px solid #cbd3de; }\n    .cover-metadata-item { min-width: 0; padding: 0 28px; border-left: 1px solid #e4e8ee; }\n    .cover-metadata-item:first-child { padding-left: 0; border-left: 0; }\n    .cover-metadata dt { margin: 0 0 13px; color: #7b8592; font-size: 12px; font-weight: 500; line-height: 1.4; }\n    .cover-metadata dd { margin: 0; color: #24364f; font-size: 17px; font-weight: 600; line-height: 1.5; letter-spacing: -0.2px; }\n  \u003c/style>\n\u003c/head>\n\u003cbody>\n  \u003cheader class=\"cover-top\">\n    \u003cdiv class=\"cover-project\">RIST\u003c/div>\n    \u003cdiv class=\"cover-category\">INTERFACE PLANNING\u003c/div>\n  \u003c/header>\n  \u003cmain class=\"cover-title-position\">\n    \u003csection class=\"cover-title\" data-component=\"cover-title\" data-component-title=\"표지 제목\" data-component-width=\"1136\">\n      \u003cdiv class=\"cover-title-accent\" aria-hidden=\"true\">\u003c/div>\n      \u003ch1>RIST 데이터 표준화 프로그램\u003c/h1>\n      \u003cp>인터페이스 기획안\u003c/p>\n    \u003c/section>\n  \u003c/main>\n  \u003cfooter class=\"cover-metadata-position\">\n    \u003cdl class=\"cover-metadata\" data-component=\"cover-metadata\" data-component-title=\"표지 문서 정보\" data-component-width=\"1136\">\n      \u003cdiv class=\"cover-metadata-item\">\u003cdt>작성자\u003c/dt>\u003cdd>그로스마케팅랩\u003c/dd>\u003c/div>\n      \u003cdiv class=\"cover-metadata-item\">\u003cdt>버전\u003c/dt>\u003cdd>v0.1\u003c/dd>\u003c/div>\n      \u003cdiv class=\"cover-metadata-item\">\u003cdt>최초 생성일\u003c/dt>\u003cdd>2026/09/16\u003c/dd>\u003c/div>\n      \u003cdiv class=\"cover-metadata-item\">\u003cdt>최종 수정일\u003c/dt>\u003cdd>2026/09/16\u003c/dd>\u003c/div>\n    \u003c/dl>\n  \u003c/footer>\n\u003c/body>\n\u003c/html>\n",
